"""sport template v5 (n110): the F2 boards are the NFL boards with the sport's stats (PTS REB AST 3PM STL BLK) in place of the
football ones — same forms, same blocks, same grids:
  PTS Grid   = TD Grid     : his slot's PTS-allowed rank in every data set side by side, ALL | G | F | C, sorted by the mean rank
  Player Grid= Player Grid : the Player Board dealt into ALL | G | F | C, showing only what the opponent allows per game to his slot
  H2H Grid   = H2H Grid    : the same grid with his own averages against this opponent
  PTS Board  = TD Board    : the Player Board built on points only
  Player Board             : player block · what the opponent allows/game to his slot with rank · his own average/game · model
  H2H Board                : the Player Board with the opponent block replaced by what he has done against this opponent
  META                     : every board folded into one score per player, in the grid's columns, best spot per signal on top
Rerunnable (guarded)."""
import os, sys
P = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'sport_template.html')
s = open(P, encoding='utf-8').read()
if 'function ptsboard()' in s:
    print('already applied'); sys.exit()
def rep(old, new):
    global s
    assert s.count(old) == 1, (s.count(old), old[:90])
    s = s.replace(old, new)
def cut(start, end_marker):
    """remove the function that starts at `start` up to (not including) end_marker"""
    global s
    a = s.index(start); b = s.index(end_marker, a); s = s[:a] + s[b:]

# ---- nav ----
rep("{id:'propboard',label:'Prop Board',fn:'propboard'},", "{id:'ptsboard',label:'PTS Board',fn:'ptsboard'},")
rep(" propboard:{what:'The prop board: per market, the model\\'s strongest leans on tonight\\'s posted lines.',how:['edge = model − market on the lean, in points · both sides priced, 8+ games of sample','click a name for his card']},",
    " ptsboard:{what:'The Player Board built on points only: what the opponent allows per game to his slot in points with its rank in every data set, his own points per game, and the model.',how:['one column per data set — a soft spot can be read as a this-season blip or as three seasons of it · μ = mean rank across the sets','PTS/G = his own: this season (big) · last five · last season','PROJ = tonight\\'s projection with its range · LINE = the posted line with the model\\'s lean and edge']},")
rep(" ptsgrid:{what:'The scoring grid: every game, each slot\\'s leading scorers against that defense.',how:['the colored number is the opponent\\'s rank allowing points to his slot (1 = allows the most)','proj = tonight\\'s projection']},",
    " ptsgrid:{what:'Points only. Each rank cell is the points tonight\\'s opponent allows to his slot in one data set, so a soft spot can be read as a this-season blip or as three seasons of it.',how:['rank 1 of 30 = allows the most = best matchup · PTS/G is the player\\'s own','the first column is every slot together, then one per slot','rows are ordered by the mean rank across the sets · every column sorts']},")
rep(" board:{what:'Every player on the slate, one row per market: projection, range and the opponent\\'s rank. Sort any column.',how:['click a header to sort','rank 1 = softest opponent for that stat']},",
    " board:{what:'The Player Board dealt into four columns — all, G, F, C — showing only what the opponent allows per game to that slot, so you can read the whole slate across positions at once.',how:['rank 1 of 30 = the defense allows the MOST to that slot (the best matchup)','one data set drives all four columns; change it at the top','every column sorts on its own · click a name for his card']},")
rep(" h2h:{what:'Head to head. The last meetings between the two teams, then every rotation player\\'s games against tonight\\'s opponent across the loaded seasons.',how:['vs = his average in those games · Δ = against his season average (green = better vs this opponent)','O-U = his record over the posted line in those games','sorted by games against the opponent; lines only = players with a posted prop']},",
    " h2h:{what:'What every rotation player has actually done against tonight\\'s opponent — his own per-game averages in every prior meeting we have logs for, in four columns by slot.',how:['vs = his average in those games · ▲ ▼ = above / below his season average · G = meetings logged','rows are ordered by how far above his season average he runs against this opponent']},")
rep(" lab:{what:'One market at a time. Every player\\'s averages and trend, the opponent\\'s rank, the projection, the posted line and his hit rate over it.',how:['pick the market with the chips · hit = share of games over the posted line (L5 · L10 · season · vs this opponent)','trend = last 5 against the season (▲ hot · ▼ cold)','lines only = players with a posted prop · starters = starter rate above 50%']},",
    " lab:{what:'Every rotation player tonight: his own averages beside what the opponent allows per game to his slot, with the rank of each — filter and sort any column.',how:['three blocks per row: the player · what the opponent allows/game to his slot with its rank of 30 (1 = allows the most; ▲ ▼ = above / below the league average for the slot) · his own average/game (big = the selected span, small = the other) · the model (Ψ = mean rank, PROJ, LINE)','slot buttons toggle and combine · every column sorts · click a name for his card']},")
rep(" h2hboard:{what:'Head to head as one ranked board: every player on the slate against tonight\\'s opponent, market by market, across the loaded seasons.',how:['Δ = his average in those games minus his season average · G = games against the opponent','sorted by the Δ in the chosen market']},",
    " h2hboard:{what:'The Player Board with the opponent block replaced by what every player has actually done against tonight\\'s opponent — his own per-game averages in every prior meeting we have logs for.',how:['vs = his average against this opponent · ▲ ▼ = above / below his season average · G = meetings','H2H = mean of his vs-opponent averages over his season averages · every column sorts']},")
rep(" meta:{what:'META: every signal on one row per player — DVP, form, head to head, minutes, home, pace, model edge — scored 0–100 within his slot and folded into one number with weights from the backtest.',how:['pick the market','weights = each signal\\'s backtested lift (Backtest tab); a signal with no lift gets no weight','click a name for his card']},",
    " meta:{what:'Every board at once: the PTS Board, Player Grid, H2H Grid, form, minutes and the prop model folded into one score per player, in the grid\\'s four columns — everyone together, then G, F and C — with tonight\\'s best spot on each signal across the top.',how:['each signal scored 0–100 within his slot · META = the weighted fold, weights = each signal\\'s backtested lift (Backtest tab)','pick the market · click a name for his card']},")

