rep("/* ---- router ---- */", r"""/* ---- v5: the NFL boards with this sport's stats ---- */
const BST=['pts','reb','ast','tpm','stl','blk'].map(k=>STAT[k]).filter(Boolean);
const SLX=['ALL'].concat(J.slots);
const oppT=t=>{const g=nextGame(t);return g?(g.away===t?g.home:g.away):''};
const univ=()=>{const T=[...new Set(GAMESD().flatMap(g=>[g.away,g.home]))].filter(inT);const out=[];T.forEach(t=>rotation(t).slice(0,J.rotation+2).forEach(p=>{if(inS(p.slot)&&(G.hm?!MISSED().has(p.pid):true)&&(!G.q||p.player.toLowerCase().includes(G.q)))out.push(p)}));return out};
let _MS=null;const MISSED=()=>{if(_MS)return _MS;const last={};J.logs.forEach(l=>{if(l[LC.season]!==J.cur)return;const t=l[LC.team];if(!last[t]||l[LC.date]>last[t])last[t]=l[LC.date]});_MS=new Set(J.players.filter(p=>last[p.team]&&(!p.last_date||p.last_date<last[p.team])).map(p=>p.pid));return _MS};
const POSC=J.sport==='basketball'?{G:'#6db3e8',F:'#a78bfa',C:'#e3b341'}:{C:'#6db3e8',W:'#a78bfa',D:'#e3b341',G:'#ef7fb0'};
const slotchip=x=>{const c=POSC[x]||'#8b98a5';return `<span class="pos" style="color:${c};border-color:${c}55">${x}</span>`};
const posIcon=(p,px=12)=>`<b class="posL" style="color:${POSC[p]||'#8b98a5'};font-size:${px}px">${p}</b>`;
const badge=r=>r==null||isNaN(r)?'<span class="dim">—</span>':`<span class="badge" style="${gradeStyle(+r)}">${(+r).toFixed(+r%1?1:0)}</span>`;
const psiOf=(opp,slot,src)=>mean(BST.map(mk=>rankOf(opp,slot,mk.k,src)).filter(Boolean).map(r=>r.rank));
const psiCell=v=>v==null||isNaN(v)?'—':`<span class="psi" style="color:${gradeColor(+v)}">${(+v).toFixed(1)}</span>`;
const spanAvg=(p,k)=>G.av==='C'?(p[k+'_all']??p[k]):p[k];const spanOther=(p,k)=>G.av==='C'?p[k]:(p[k+'_all']??p[k+'_prior']);
const lgridHTML=id=>`<div class="lgrid">${SLX.map(sl=>`<section class="lgcol"><h3>${sl==='ALL'?'◉ all':posIcon(sl,12)+' '+sl} <span class="f" id="${id}N${sl}"></span></h3><div id="${id}B${sl}"></div></section>`).join('')}</div>`;
const posTabs=(id)=>{if(!G.pos)G.pos=new Set(['ALL']);return `<div class="tabs" id="${id}"><button data-p="ALL" class="${G.pos.has('ALL')?'on':''}">ALL</button>${J.slots.map(sl=>`<button data-p="${sl}" class="${G.pos.has(sl)?'on':''}" title="click to toggle · combine several">${posIcon(sl,12)} ${sl}</button>`).join('')}</div>`};
const bindTabs=(el,id,fn)=>el.querySelectorAll('#'+id+' button').forEach(b=>b.onclick=()=>{const p=b.dataset.p;if(p==='ALL')G.pos=new Set(['ALL']);else{G.pos.delete('ALL');G.pos.has(p)?G.pos.delete(p):G.pos.add(p);if(!G.pos.size)G.pos=new Set(['ALL'])}fn()});
const posOK=p=>!G.pos||G.pos.has('ALL')||G.pos.has(p.slot);
const boardCtl=(fn)=>`<select id="bAv" title="which of the player's own per-game averages leads each avg cell — the other sits small beside it"><option value="S" ${G.av!=='C'?'selected':''}>player avg: this season</option><option value="C" ${G.av==='C'?'selected':''}>player avg: ${J.seasons[0]}–${String(J.seasons[J.seasons.length-1]).slice(2)}</option></select><select id="bHm"><option value="x" ${G.hm!==false?'selected':''}>hide missing</option><option value="" ${G.hm===false?'selected':''}>incl. missing</option></select><input id="bQ" placeholder="search player…" size="16" value="${esc(G.q||'')}">`;
const bindCtl=(el,fn)=>{$('#bAv').onchange=()=>{G.av=$('#bAv').value;fn()};$('#bHm').onchange=()=>{G.hm=$('#bHm').value==='x';fn()};$('#bQ').oninput=()=>{G.q=$('#bQ').value.trim().toLowerCase();fn()}};
if(G.hm===undefined)G.hm=true;
const avgCell=(p,k,o,dec)=>{const big=spanAvg(p,k),sm=spanOther(p,k);if(big==null&&sm==null)return '<span class="dim">—</span>';const ar=o!=null&&big!=null?(o>big+1e-9?'<i class="pa-up" title="opponent allows more than he averages">▲</i>':o<big-1e-9?'<i class="pa-dn" title="opponent allows less than he averages">▼</i>':''):'';return `<b>${fmt(big,dec)}</b>${ar}<span class="mini"> ${fmt(sm,dec)}</span>`};
const modelCells=p=>{const pj=PJ[p.pid]&&PJ[p.pid].pts;const ln=LINES[p.pid]&&LINES[p.pid].pts;return `<td class="md" data-v="${pj?pj.proj:-1}">${pj?`<b>${fmt(pj.proj,1)}</b> <span class="mini">${fmt(pj.q10,0)}-${fmt(pj.q90,0)}</span>`:'—'}</td><td class="md" data-v="${ln?ln.edge:-1}">${ln?`<span class="mono">${ln.line}</span> ${lean(ln)}`:'<span class="dim">—</span>'}</td>`};
/* Player Board / H2H Board: one builder, two opponent blocks */
function boardTable(el,mode,fn){const U=univ().filter(posOK).map(p=>{const opp=oppT(p.team);const L=mode==='h2h'?logsOf(p.pid).filter(l=>l[LC.opp]===opp):null;
    const cells=BST.map(mk=>{if(mode==='h2h'){const v=mean(L.map(l=>lval(l,mk.k)));return {v,r:null,base:spanAvg(p,mk.k)}}const r=rankOf(opp,p.slot,mk.k);return {v:r?r.avg:null,r:r?r.rank:null,lg:r?r.lg:null,base:spanAvg(p,mk.k)}});
    const psi=mode==='h2h'?(()=>{const q=cells.map(c=>c.v!=null&&c.base?c.v/c.base:null).filter(v=>v!=null);return q.length?100*(mean(q)-1):null})():psiOf(opp,p.slot);return {p,opp,cells,psi,n:L?L.length:null}}).filter(x=>mode!=='h2h'||x.n);
  U.sort((a,b)=>mode==='h2h'?(b.psi??-999)-(a.psi??-999):(a.psi??99)-(b.psi??99));
  const span=G.av==='C'?`${J.seasons[0]}–${String(J.seasons[J.seasons.length-1]).slice(2)}`:String(J.cur),other=G.av==='C'?String(J.cur):`${J.seasons[0]}–${String(J.seasons[J.seasons.length-1]).slice(2)}`;
  el.innerHTML=`${posTabs('bTabs')}<div class="controls">${boardCtl()}<span class="note">${U.length} players · three blocks per row: the player · <b>${mode==='h2h'?'his own average/game against tonight\'s opponent in every logged meeting (G = meetings; ▲ ▼ = above / below his season average)':'what the opponent allows/game to his slot'} ${mode==='h2h'?'':'with its rank of '+NT+' (1 = allows the most; ▲ ▼ = above / below the league average for the slot) · '+G.src}</b> · <b>his own average/game</b> (big = ${span}, small = ${other}) · the model (${mode==='h2h'?'H2H = mean of his vs-opponent averages over his season averages':'Ψ = mean of the opponent\'s ranks across the six stats'} · PROJ = tonight\'s points with its range · LINE = the posted points line, lean and edge) · slot buttons toggle and combine · every column sorts · click a name for his card</span></div>
   <div class="panel wrap-x"><table class="lab2"><thead><tr class="grp"><th colspan="6" class="g0">player</th><th colspan="${BST.length+(mode==='h2h'?1:0)}" class="op">${mode==='h2h'?'his average/game vs tonight\'s opponent · all logged meetings':`opponent allows/game to his slot · rank of ${NT} · ${G.src}`}</th><th colspan="${BST.length+1}" class="pa">player average/game · <b>${span}</b> <span>· small = ${other}</span></th><th colspan="3" class="md">model</th></tr>
   <tr><th>Player</th><th>Tm</th><th>Slot</th><th>Opp</th><th>Tip</th><th title="minutes per game">MIN</th>${mode==='h2h'?'<th class="gs" title="meetings logged">G</th>':''}${BST.map((mk,i)=>`<th class="op${i===0&&mode!=='h2h'?' gs':''}" title="${mk.label} ${mode==='h2h'?'per game against this opponent':'allowed per game to his slot · badge = rank of '+NT}">${mk.label}</th>`).join('')}${BST.map((mk,i)=>`<th class="pa${i===0?' gs':''}" title="${mk.label}: his own per-game average">${mk.label}</th>`).join('')}<th class="pa" title="games: this season · all seasons">GP</th><th class="md" title="${mode==='h2h'?'mean of his vs-opponent averages over his season averages, in %':'mean of the opponent\'s ranks across the six stats · 1 = softest'}">${mode==='h2h'?'H2H':'Ψ'}</th><th class="md" title="projected points with its range">PROJ</th><th class="md" title="the posted points line · lean · edge">LINE</th></tr></thead><tbody>
   ${U.map(x=>{const p=x.p;const g=nextGame(p.team);return `<tr><td>${pname(p)}${MISSED().has(p.pid)?' <span class="res L" title="missed his team\'s last game">OUT?</span>':''}</td><td>${tc(p.team)}</td><td>${slotchip(p.slot)}</td><td class="mini">${oppOf(p.team)}</td><td class="mini">${g?fmtT(g.date):''}</td><td class="mono mini">${fmt(his(p,'min'),0)}</td>${mode==='h2h'?`<td class="gs mono">${x.n}</td>`:''}
     ${x.cells.map((c,i)=>mode==='h2h'?`<td class="op" data-v="${c.v??-1}"><span class="ov">${fmt(c.v,BST[i].dec)}</span>${c.v!=null&&c.base!=null?(c.v>c.base+1e-9?'<i class="pa-up">▲</i>':c.v<c.base-1e-9?'<i class="pa-dn">▼</i>':''):''}</td>`:`<td class="op${i===0?' gs':''}" data-v="${c.r??99}"><span class="ov">${fmt(c.v,BST[i].dec)}${c.v!=null&&c.lg!=null?(c.v>c.lg*1.03?'<i class="pa-up" title="above the league average for the slot">▲</i>':c.v<c.lg*.97?'<i class="pa-dn" title="below the league average for the slot">▼</i>':''):''}</span>${badge(c.r)}</td>`).join('')}
     ${x.cells.map((c,i)=>`<td class="pa${i===0?' gs':''}" data-v="${spanAvg(p,BST[i].k)??-1}">${avgCell(p,BST[i].k,null,BST[i].dec)}</td>`).join('')}<td class="pa mini" data-v="${G.av==='C'?p.gp_all:p.gp}"><b>${G.av==='C'?p.gp_all:p.gp}</b> · ${G.av==='C'?p.gp:p.gp_all}</td>
     <td class="md" data-v="${x.psi??(mode==='h2h'?-999:99)}">${mode==='h2h'?(x.psi==null?'·':`<b class="${x.psi>0?'rise':'fall'}">${x.psi>0?'+':''}${x.psi.toFixed(0)}%</b>`):psiCell(x.psi)}</td>${modelCells(p)}</tr>`}).join('')}</tbody></table></div>`;
  bindTabs(el,'bTabs',fn);bindCtl(el,fn);bindPL(el)}
function lab(){boardTable($('#match'),'dvp',lab)}
function h2hboard(){boardTable($('#match'),'h2h',h2hboard)}
/* PTS Board = the TD Board: points only, one column per data set */
function ptsboard(){const el=$('#match');const srcs=Object.keys(J.dvp);const U=univ().filter(posOK).map(p=>{const opp=oppT(p.team);const cells=srcs.map(sr=>rankOf(opp,p.slot,'pts',sr));const got=cells.filter(Boolean).map(r=>r.rank);return {p,opp,cells,mu:got.length?mean(got):null}}).sort((a,b)=>(a.mu??99)-(b.mu??99));
  el.innerHTML=`${posTabs('bTabs')}<div class="controls">${boardCtl()}<span class="note">points only · ${U.length} players · each cell: the <b>points tonight's opponent allows per game to his slot</b> in one data set with its rank of ${NT} (1 = allows the most = best matchup) · μ = mean rank across the sets · <b>PTS/G is the player's own</b>: this season (big) · last five · last season · PROJ and LINE from the model · slot buttons toggle and combine · every column sorts</span></div>
   <div class="panel wrap-x"><table class="lab2"><thead><tr class="grp"><th colspan="6" class="g0">player</th><th colspan="${srcs.length+1}" class="op">points allowed/game to his slot · rank of ${NT}</th><th colspan="3" class="pa">his own points/game</th><th colspan="2" class="md">model</th></tr><tr><th>Player</th><th>Tm</th><th>Slot</th><th>Opp</th><th>Tip</th><th>MIN</th>${srcs.map((sr,i)=>`<th class="op${i===0?' gs':''}">${sr}</th>`).join('')}<th class="op" title="mean rank across the data sets">μ</th><th class="pa gs" title="this season">${J.cur}</th><th class="pa" title="last five games">L5</th><th class="pa" title="last season">${J.prior}</th><th class="md">PROJ</th><th class="md">LINE</th></tr></thead><tbody>
   ${U.map(x=>{const p=x.p;const g=nextGame(p.team);return `<tr><td>${pname(p)}${MISSED().has(p.pid)?' <span class="res L" title="missed his team\'s last game">OUT?</span>':''}</td><td>${tc(p.team)}</td><td>${slotchip(p.slot)}</td><td class="mini">${oppOf(p.team)}</td><td class="mini">${g?fmtT(g.date):''}</td><td class="mono mini">${fmt(his(p,'min'),0)}</td>${x.cells.map((r,i)=>`<td class="op${i===0?' gs':''}" data-v="${r?r.rank:99}"><span class="ov">${r?fmt(r.avg,1):'·'}</span>${badge(r?r.rank:null)}</td>`).join('')}<td class="op" data-v="${x.mu??99}">${psiCell(x.mu)}</td><td class="pa gs mono" data-v="${p.pts??-1}"><b>${fmt(p.pts,1)}</b></td><td class="pa mono" data-v="${p.pts_l5??-1}">${fmt(p.pts_l5,1)}</td><td class="pa mono dim" data-v="${p.pts_prior??-1}">${fmt(p.pts_prior,1)}</td>${modelCells(p)}</tr>`}).join('')}</tbody></table></div>`;
  bindTabs(el,'bTabs',ptsboard);bindCtl(el,ptsboard);bindPL(el)}
/* the grids: ALL | G | F | C side by side */
function gridRender(el,id,note,rowsFor,head,row){el.innerHTML=`<div class="controls">${boardCtl()}<span class="note">${note}</span></div>${lgridHTML(id)}`;
  SLX.forEach(sl=>{const R=rowsFor(sl);$('#'+id+'N'+sl).textContent=R.length+(R.length===1?' player':' players');$('#'+id+'B'+sl).innerHTML=`<table class="lgt"><thead><tr>${head(sl)}</tr></thead><tbody>${R.map(x=>row(x,sl)).join('')}</tbody></table>`});bindPL(el);sortableAll(el)}
function ptsgrid(){const el=$('#match');const srcs=Object.keys(J.dvp);const all=univ().map(p=>{const opp=oppT(p.team);const cells=srcs.map(sr=>{const r=rankOf(opp,p.slot,'pts',sr);return r?r.rank:null});const got=cells.filter(v=>v!=null);return {p,opp,cells,mu:got.length?mean(got):null}}).sort((a,b)=>(a.mu??99)-(b.mu??99));
  gridRender(el,'pg',`points only · each rank cell is the <b>points tonight's opponent allows to his slot</b> in one data set · rank 1 of ${NT} = allows the most = best matchup · <b>PTS/G is the player's own</b> this season · the first column is every slot together, then one per slot · rows ordered by the mean rank across the sets`,
    sl=>sl==='ALL'?all:all.filter(x=>x.p.slot===sl),
    sl=>`<th>Player</th>${sl==='ALL'?'<th></th>':''}<th>Opp</th><th title="his own points per game this season">PTS/G</th>${srcs.map(sr=>`<th title="points allowed to his slot · ${sr} · rank of ${NT}">${sr==='combined'?'comb':String(sr).slice(2)}</th>`).join('')}<th title="mean rank across the sets">μ</th>`,
    (x,sl)=>`<tr><td class="pn">${pname(x.p)}</td>${sl==='ALL'?`<td>${slotchip(x.p.slot)}</td>`:''}<td class="op2">${x.opp}</td><td class="mono" data-v="${x.p.pts??-1}">${fmt(x.p.pts,1)}</td>${x.cells.map(r=>`<td data-v="${r??99}">${badge(r)}</td>`).join('')}<td data-v="${x.mu??99}">${x.mu==null?'·':`<b style="color:${gradeColor(x.mu)}">${x.mu.toFixed(1)}</b>`}</td></tr>`);
  bindCtl(el,ptsgrid)}
function board(){const el=$('#match');const all=univ().map(p=>{const opp=oppT(p.team);const cells=BST.map(mk=>rankOf(opp,p.slot,mk.k));return {p,opp,cells,psi:psiOf(opp,p.slot)}}).sort((a,b)=>(a.psi??99)-(b.psi??99));
  gridRender(el,'lg',`the Player Board dealt into four columns, showing only <b>what tonight's opponent allows per game to his slot</b> with its rank of ${NT} (1 = allows the most) · data set: ${G.src} · Ψ = mean rank across the six stats · rows ordered by Ψ · every column sorts`,
    sl=>sl==='ALL'?all:all.filter(x=>x.p.slot===sl),
    sl=>`<th>Player</th>${sl==='ALL'?'<th></th>':''}<th>Opp</th>${BST.map(mk=>`<th title="${mk.label} allowed per game to his slot · badge = rank">${mk.label}</th>`).join('')}<th>Ψ</th>`,
    (x,sl)=>`<tr><td class="pn">${pname(x.p)}</td>${sl==='ALL'?`<td>${slotchip(x.p.slot)}</td>`:''}<td class="op2">${x.opp}</td>${x.cells.map((r,i)=>`<td data-v="${r?r.rank:99}" style="white-space:nowrap"><span class="op2">${r?fmt(r.avg,BST[i].dec):'·'}</span> ${badge(r?r.rank:null)}</td>`).join('')}<td data-v="${x.psi??99}">${x.psi==null?'·':`<b style="color:${gradeColor(x.psi)}">${x.psi.toFixed(1)}</b>`}</td></tr>`);
  bindCtl(el,board)}
function h2h(){const el=$('#match');const all=univ().map(p=>{const opp=oppT(p.team);const L=logsOf(p.pid).filter(l=>l[LC.opp]===opp);const cells=BST.map(mk=>({v:mean(L.map(l=>lval(l,mk.k))),base:spanAvg(p,mk.k)}));const q=cells.map(c=>c.v!=null&&c.base?c.v/c.base:null).filter(v=>v!=null);return {p,opp,n:L.length,cells,d:q.length?100*(mean(q)-1):null}}).filter(x=>x.n).sort((a,b)=>(b.d??-999)-(a.d??-999));
  gridRender(el,'hg',`what every rotation player has actually done against tonight's opponent — <b>his own per-game averages in every logged meeting</b> (G = meetings) · ▲ ▼ = above / below his season average · H2H = mean of those averages over his season averages · rows ordered by H2H`,
    sl=>sl==='ALL'?all:all.filter(x=>x.p.slot===sl),
    sl=>`<th>Player</th>${sl==='ALL'?'<th></th>':''}<th>Opp</th><th title="meetings logged">G</th>${BST.map(mk=>`<th title="${mk.label} per game against this opponent">${mk.label}</th>`).join('')}<th>H2H</th>`,
    (x,sl)=>`<tr><td class="pn">${pname(x.p)}</td>${sl==='ALL'?`<td>${slotchip(x.p.slot)}</td>`:''}<td class="op2">${x.opp}</td><td class="mono">${x.n}</td>${x.cells.map((c,i)=>`<td class="mono" data-v="${c.v??-1}" style="white-space:nowrap">${fmt(c.v,BST[i].dec)}${c.v!=null&&c.base!=null?(c.v>c.base+1e-9?'<i class="pa-up">▲</i>':c.v<c.base-1e-9?'<i class="pa-dn">▼</i>':''):''}</td>`).join('')}<td data-v="${x.d??-999}">${x.d==null?'·':`<b class="${x.d>0?'rise':'fall'}">${x.d>0?'+':''}${x.d.toFixed(0)}%</b>`}</td></tr>`);
  bindCtl(el,h2h)}
/* META = every board folded into one score, in the grid's columns */
function meta(){const el=$('#match');const k=G.lm||'pts';const {ps,W}=metaRows(k);const top=SIG.map(([id,l])=>{const b=ps.filter(x=>x[id]!=null).sort((a,c)=>c[id]-a[id])[0];return b?`<span class="chip on" style="font-size:10px">${l}: ${esc(b.p.player)} ${b[id].toFixed(0)}</span>`:''}).join(' ');
  el.innerHTML=`<div class="controls">${mkSel('mkS')}<span class="note">every board folded into one score per player · ${MKL[k]} · each signal 0–100 within his slot: DVP (the opponent's rank for his slot), form (L5 vs season), H2H (vs this opponent), minutes, home, pace, model edge (the prop line) · META = weighted fold, weights from the backtest (${SIG.map(([id,l])=>`${l} ${W[id].toFixed(2)}`).join(' · ')}) · everyone together, then one column per slot</span></div><div class="panel"><h3>tonight's best spot on each signal</h3>${top}</div>${lgridHTML('mg')}`;
  SLX.forEach(sl=>{const R=sl==='ALL'?ps:ps.filter(x=>x.p.slot===sl);$('#mgN'+sl).textContent=R.length+' players';$('#mgB'+sl).innerHTML=`<table class="lgt"><thead><tr><th>Player</th>${sl==='ALL'?'<th></th>':''}<th>Opp</th><th>META</th>${SIG.map(([id,l])=>`<th class="${W[id]>0?'':'nw'}" title="${l}">${{dvp:'DVP',form:'FORM',h2h:'H2H',usage:'MIN',home:'HM',pace:'PACE',edge:'EDGE'}[id]}</th>`).join('')}</tr></thead><tbody>${R.map(x=>`<tr><td class="pn">${pname(x.p)}</td>${sl==='ALL'?`<td>${slotchip(x.p.slot)}</td>`:''}<td class="op2">${x.S.opp}</td><td data-v="${x.meta??-1}"><span class="hc sm" style="${gradeStyle(x.meta==null?null:1+(NT-1)*(1-x.meta/100))}">${x.meta!=null?x.meta.toFixed(0):'·'}</span></td>${SIG.map(([id])=>`<td class="mono" data-v="${x[id]??-1}" style="color:${x[id]==null?'var(--dim)':x[id]>=70?'var(--green)':x[id]<=30?'var(--red)':'var(--txt)'}">${x[id]!=null?x[id].toFixed(0):'·'}</td>`).join('')}</tr>`).join('')}</tbody></table>`});
  bindMk(el,meta);bindPL(el);sortableAll(el)}
/* ---- router ---- */""")
assert 'gradeColor' in s
open(P, 'w', encoding='utf-8').write(s)
print('applied')
